async fn test_ocr_error_400() {
    // 400 Bad Request error when OCR input has an invalid image format
    let mock_route = MockRoute {
        path: "/ocr",
        method: "POST",
        status: 400,
        body: r#"{"error":{"code":"invalid_image","message":"Invalid image format","type":"invalid_request_error"}}"#
            .to_string(),
        is_streaming: false,
        stream_chunks: vec![],
        headers: vec![],
        delay_ms: None,
    };
    let mock_server = MockServer::start(vec![mock_route]).await;
    let req_json: serde_json::Value = serde_json::from_str(
        r#"{"document":{"type":"document_url","url":"invalid://url"},"model":"mistral/mistral-ocr-latest"}"#,
    )
    .unwrap();
    let req = serde_json::from_value(req_json).unwrap();
    let client =
        liter_llm::create_client("test-key".to_string(), Some(mock_server.url.clone()), None, None, None).unwrap();
    let result = client.ocr(req).await;
    assert!(result.is_err(), "expected call to fail");
    {
        let __e = result.as_ref().err().unwrap();
        assert!(
            format!("{:?}", __e).contains("BadRequest") || __e.to_string().contains("BadRequest"),
            "error message mismatch"
        );
    }
    assert_eq!(
        {
            let __err = result.as_ref().err().unwrap();
            __err.status_code()
        },
        400,
        "equals assertion failed"
    );
}

